#!/usr/bin/env python3
"""Build the Reconstruction review study guide from the verbatim
vocabulary in build-scripts/unit-spec.md, plus 24 review questions
with a full key, a plain prose frame passage answering the unit
essential question, and the fifteen entries of the unit blueprint
restated in student language. Mirrors the Sectional Crisis and Civil
War study guide. The teacher key carries no blueprint tags."""
import os, re

HERE = os.path.dirname(os.path.abspath(__file__))
UNIT = os.path.dirname(HERE)
SPEC = open(os.path.join(HERE, "unit-spec.md")).read()

LESSON_TITLES = {
    1: "After Appomattox: Presidential Reconstruction",
    2: "The Thirteenth Amendment and the Meaning of Freedom",
    3: "Congress Takes Charge: The Fourteenth Amendment and the Reconstruction Acts",
    4: "The New Political Order: The Vote and Black Officeholding",
    5: "Freedom on the Ground: Land, Labor, Schools, and Churches",
    6: "The Counterrevolution: The Klan and the Enforcement Acts",
    7: "The Retreat: Courts, Panic, and the Leagues",
    8: "1876 and the End: What Was Settled, What Was Left Open",
}

def parse_terms():
    terms = {}
    current = None
    in_vocab = False
    for line in SPEC.splitlines():
        if line.startswith("## Vocabulary"):
            in_vocab = True
            continue
        if in_vocab and line.startswith("## "):
            break
        if not in_vocab:
            continue
        m = re.match(r"### Lesson (\d)", line)
        if m:
            current = int(m.group(1)); terms[current] = []
            continue
        m = re.match(r"- ([^:]+): (.+)$", line)
        if m and current:
            terms[current].append((m.group(1).strip(), m.group(2).strip()))
    return terms

QUESTIONS = [
    (1, "What did Johnson's restoration program offer the seceded states from April 1865, and what three acts did it require of their conventions?",
     "Johnson, the Tennessee Unionist who became president on Lincoln's assassination in April 1865, ran restoration from the White House while Congress was away. His Amnesty Proclamation of May 29, 1865 pardoned most former Confederates who swore a loyalty oath and restored their property except in enslaved people, while fourteen excepted classes, high officers and the wealthy among them, had to apply to him personally. The states could organize governments once they abolished slavery, repudiated their secession ordinances and their Confederate debts, and were readmitted without terms from Congress. What the restored governments did with Black freedom Johnson left to those governments themselves, and the governments they built, often led by former Confederates, answered in the fall of 1865 with the Black Codes."),
    (1, "What did the Freedmen's Bureau do across the South, and where did its agents stand between freedpeople and planters?",
     "Congress created the Bureau in March 1865, formally the Bureau of Refugees, Freedmen, and Abandoned Lands, the first federal relief agency in American history. It fed the hungry of both races, ran hospitals and courts, supervised the labor contracts freedpeople signed with planters, legalized marriages the slave law had not recognized, and built schools across the South. Its agents stood in an impossible place. A freed family wanted a contract that paid wages, protected its children from apprenticeship, and left time for school. A planter wanted a workforce bound for the year on terms close to the old discipline. The Bureau agent wrote and enforced the contracts between those two sets of terms, with too few agents for the ground he covered, and Johnson's restoration of confiscated and abandoned land to pardoned owners stripped the agency of the one asset, land, that might have made its contracts bargains between equals."),
    (1, "How did the Black Codes rebuild labor control in law, and how did Jourdon Anderson and the Edisto Island petitioners answer the settlement of 1865 in their own words?",
     "The restored governments passed the Black Codes in 1865 and 1866. Mississippi's Vagrant Law is the unit's working text: freedmen over eighteen found with no lawful employment or business could be fined as vagrants, Black children could be apprenticed by force, and contract rules tied a laborer who left before the year ended to arrest and lost wages. The codes also denied freedpeople equal rights of testimony, arms, and property. Freedpeople answered in their own words. Jourdon Anderson of Tennessee, invited back by his former enslaver, dictated a letter demanding wages for thirty two years of his own labor and twenty for his wife's, and asked whether his daughters would be safe and his children schooled before he would consider returning. The freedpeople settled on Edisto Island petitioned against losing the land they had been settled on under Sherman's order, stating that they had worked it and asking to buy it, freedom's land claim made by the people who held the plots."),
    (2, "State what the Thirteenth Amendment says, how it was ratified in December 1865, and what its second section gives Congress.",
     "The amendment's first section abolishes slavery and involuntary servitude everywhere in the United States, except as punishment for a crime, an exception clause whose later use in convict leasing the unit names in one sentence. Congress had passed it on January 31, 1865, while the war still ran. Ratification then ran through the states in 1865, with the border states resisting and the restored southern states ratifying under Johnson's pressure, since abolition was one of his three required acts. Georgia's vote completed the count, and the amendment was proclaimed ratified in December 1865, the only one of the three Reconstruction amendments adopted in the war's own year. Its second section gives Congress power to enforce the article by appropriate legislation. That clause made Congress freedom's author and not only its witness, and it was the ground Congress stood on when it moved from the amendment to a civil rights statute the next spring."),
    (2, "What did the freedmen's conventions of 1865 and 1866 demand, and what else did freedpeople build and repair in freedom's first year?",
     "Freedpeople held state conventions across the South in 1865 and 1866, electing delegates, organizing their communities, and petitioning as citizens. Their demands ran on one line: land, fair wages, protection for their families, schools for their children, and the ballot. The conventions were the first political assemblies of the emancipated, and their petitions taught Congress what the Black Codes were answering. Around the conventions, freed families did the work emancipation had left undone in private life. They searched for children and kin sold away under slavery, placing notices and walking the roads the trade had used. They legalized marriages that slavery had refused to recognize in law. They chose names of their own. The conventions stated freedom's terms in public; the searches, marriages, and names carried the same terms into the household."),
    (2, "How did the Civil Rights Act of 1866 become law, and why did its supporters conclude that a statute was not enough?",
     "Lyman Trumbull of Illinois, chairman of the Judiciary Committee and a moderate, wrote the Civil Rights Act to answer the Black Codes. It declared all persons born in the United States citizens and guaranteed citizens of every race the same rights to contract, sue, hold property, and enjoy the law's protection. Johnson vetoed it, as he had vetoed Trumbull's Freedmen's Bureau bill. In April 1866 Congress passed the Civil Rights Act over his veto, the first statute enacted over a presidential veto on a major measure, and the Republican center followed Trumbull into congressional Reconstruction. The statute's supporters then drew the lesson of the fight. A law passed over one veto could be narrowed by courts that doubted Congress had power to write it at all, since the Constitution as it stood named no birthright citizenship and no equal protection for Congress to enforce. Freedom needed the Constitution itself rewritten, which is the work the Fourteenth Amendment was drafted to do."),
    (3, "State the work each section of the Fourteenth Amendment does, naming the clauses of Section 1 in their own terms.",
     "Congress proposed the amendment in June 1866 and the states ratified it in 1868. Section 1 writes citizenship into the Constitution: all persons born or naturalized in the United States, and subject to its jurisdiction, are citizens of the United States and of the state where they reside. The same section forbids any state to abridge citizens' privileges or immunities, to deprive any person of life, liberty, or property without due process of law, or to deny any person equal protection of the laws. Section 2 cuts the House representation of a state that disfranchises its male voters. Section 3 bars leading former Confederates from office unless Congress removes the disability by a two thirds vote. Section 4 guarantees the Union's debt and voids the Confederacy's. Drafted as the Civil Rights Act's constitutional armor, it carried more than the statute had: a definition of citizenship no court could read out, and rules for representation, office, and debt that rebuilt the Union on the settlement's terms."),
    (3, "State the terms of the Reconstruction Acts of March 1867, and state what Tennessee's course showed that the other ten states refused.",
     "The acts, passed over Johnson's veto in March 1867, set aside the existing governments of the ten unreconstructed southern states and divided them into five military districts, each under a Union general empowered to register voters, supervise elections and conventions, remove officials, and protect persons and property where civil authority would not. The electorate the generals registered included Black men. Each state had to call a convention, write a new constitution guaranteeing Black male suffrage, ratify the Fourteenth Amendment, and win Congress's approval before its representatives were readmitted. Tennessee showed the road the ten refused. It had ratified the Fourteenth Amendment in 1866 and was readmitted to representation at once, outside the acts entirely. The other ten states rejected the amendment in 1866 and 1867, many by overwhelming votes, and the acts were Congress's answer to that refusal, imposing as a price of return what the states would not accept as a condition offered."),
    (3, "How did the fight over Edwin M. Stanton's removal become the impeachment of Andrew Johnson, and how did the trial end?",
     "The Tenure of Office Act of March 1867, passed over Johnson's veto, forbade the president to remove officials confirmed by the Senate without the Senate's consent. It was written to protect Edwin M. Stanton, Lincoln's secretary of war, who held his post into Johnson's administration and sided with Congress against the president's policy. In February 1868 Johnson removed Stanton in defiance of the act. The House impeached him, charging articles built on the removal, and the Senate tried the charges in the spring of 1868. The vote to convict fell one short of the two thirds the Constitution requires, and Johnson served out his term. The presidency was weakened, Johnson made no further open defiance of the settlement, and the congressional program survived its maker of resistance intact, with the elections of 1868 and the readmissions of that summer running under the acts rather than under restoration."),
    (4, "How was the electorate of 1867 and 1868 made, and what did the conventions it elected write into the new state constitutions?",
     "Registration under the Reconstruction Acts enrolled some seven hundred thousand Black voters in the ten states where none had voted before, alongside white voters, with former Confederate leaders barred in part by the Fourteenth Amendment's disability. The Union League, spreading through the South from 1867 as patriotic clubs under the Loyal League name, did the organizing, meeting in churches and schoolhouses to register voters, teach the new politics, and turn out the electorate the acts created. The conventions of 1867 and 1868, elected by that electorate, wrote the most democratic charters the South had known. The new constitutions established the South's first public school systems, wrote civil rights into state law, made taxation fairer by reaching property that the old charters had sheltered, and opened office and jury service beyond the planter class. The governments that followed were coalitions, of Black voters, of white southern Republicans whom Democrats named scalawags, and of northern newcomers whom Democrats named carpetbaggers, the hostile labels hiding the coalition the next question names."),
    (4, "Name the three Black officeholders this unit follows to the top of the new order, and state the office each reached and one thing each did there.",
     "Hiram Rhodes Revels of Mississippi, a minister freeborn in North Carolina who had recruited Black regiments and served as a Union army chaplain, was elected to the United States Senate in 1870, the first Black member of Congress, seated in the chamber Jefferson Davis had left. In the Senate he argued for desegregating the District of Columbia schools. Blanche K. Bruce of Mississippi, born enslaved in Virginia, rose through tax and education offices to election to the Senate in 1874, the second Black senator and the first to serve a full term, seated while the settlement that elected him was already being dismantled. P. B. S. Pinchback of Louisiana, freeborn in Georgia and a Union officer in the war, rose through the state senate to serve as acting governor of Louisiana for five weeks in the winter of 1872 and 1873, the first Black man to govern an American state. Beneath them stood Black legislators by the hundreds in the statehouses, and Black sheriffs, school officers, and justices across the South's counties."),
    (4, "State the Fifteenth Amendment's text closely, what it leaves open, and the split its coming opened among old allies.",
     "Congress proposed the amendment in February 1869 and the states ratified it in February 1870. It forbids the United States and the states to deny or abridge a citizen's right to vote on account of race, color, or previous condition of servitude. What it forbids is denial on those three grounds, and its silences are part of the unit's record. It does not forbid a literacy test, a poll tax, or a property qualification written without naming race, the loopholes through which disfranchisement would later be built. It does not give the vote to women of any race. Its drafting split the alliance of abolition and women's rights that had run since before the war. Some woman suffrage leaders refused to support an amendment that protected Black men's voting while leaving women of every race outside it, and others held that this was, in the phrase of the fight, the Negro's hour, and carried the amendment. The alliance broke over the question and did not reunite in the era."),
    (5, "Trace the land settlement from Special Field Orders No. 15 to its reversal, and state the other land plan Congress refused.",
     "On January 16, 1865, General William T. Sherman's Special Field Orders No. 15 reserved the Sea Islands and a coastal strip of South Carolina, Georgia, and Florida for settlement by freed families in plots of not more than forty acres, and the army lent mules to the settlers, the origin of the freedpeople's shorthand, forty acres and a mule. Some forty thousand freedpeople settled on the reserve. Johnson's restoration then undid the settlement: pardoned owners reclaimed their land, and the federal government restored the plots to the former owners, which is what the Edisto Island petitioners were answering when they petitioned to keep and buy the land they had worked. In Congress, Thaddeus Stevens argued the larger plan, confiscation of the great planters' estates to give freed families land of their own, and Congress refused it. The Southern Homestead Act offered poor public acres instead and reached few families. The land question was thus decided by refusal: emancipation changed the laborer's legal standing and left the region's land in the hands that had held it under slavery."),
    (5, "How did sharecropping work, and how did the crop lien turn one year's settlement into the next year's debt?",
     "Sharecropping spread across the cotton South as the compromise nobody chose on purpose. Freedpeople refused the supervised gang labor of slavery and of the first contracts, and landowners refused to sell land or pay steady wages. A family instead farmed a plot of a landowner's land for a share of the crop, commonly half, working its own plot with its own labor and settling accounts once a year. The crop lien financed the year. A furnishing merchant advanced seed, tools, food, and clothing against a legal claim on the crop before it was planted, at prices and interest the merchant set. At settlement the crop was sold, the merchant's account was paid first, and in a poor year, or on a disputed account, what remained did not cover the advance. The family began the next year in debt, signing a new lien to eat while the new crop grew, so the system renewed itself at every settlement without any law ordering a family to stay."),
    (5, "What did freedpeople build in schools and churches, and what did the Freedmen's Savings Bank's failure cost them?",
     "Freedpeople founded the freedmen's schools, taxed themselves to sustain them, built schoolhouses, and filled them, taught by Black teachers and by northern missionaries under Bureau and church sponsorship. Some quarter of a million students were enrolled by 1870, and the schools laid the foundation of the South's first public school systems. The churches rose beside them. The African Methodist Episcopal Church, the independent Black denomination organized in Philadelphia in 1816, carried its churches across the South by the thousands after emancipation, alongside independent Baptist congregations. A meetinghouse was often the first property a Black community owned outright, and it doubled as a schoolhouse and a league hall, its minister doubling as an organizer of the new politics. Savings were the third building. The Freedmen's Savings Bank, chartered by Congress in March 1865, took in the deposits of tens of thousands of Black soldiers and freed families. Speculation and the Panic of 1873 brought it down in 1874, and its depositors lost much of what they had saved, a failure that cost freed families capital the land settlement had already denied them."),
    (6, "What did the Ku Klux Klan aim at, and how did night riding work as its method?",
     "The Klan was founded at Pulaski, Tennessee, in 1866 and spread across the South as the Invisible Empire, a secret terrorist organization whose purpose was political: to destroy the Reconstruction governments by destroying their electorate. Its targets were the people who made those governments run, Black voters, Republican organizers, teachers in the freedmen's schools, and officeholders. Its method was night riding. Mounted men in disguises rode after dark to a target's house, called him out by name, and whipped or shot him, with terror timed to elections, school terms, and contract settlements. The timing is the argument: an attack on one man before an election instructed a whole community in what voting, teaching, or organizing would cost. Nathan Bedford Forrest, the former Confederate cavalry general and Memphis slave trader elected the Klan's first Grand Wizard in 1867, ordered the organization dissolved in 1869 as its violence escaped control, and denied directing it when Congress questioned him in 1871, denials the testimony record lets students weigh for themselves."),
    (6, "State what Abram Colby told Congress was done to him, what he was offered before it, and what he refused.",
     "Abram Colby was a Georgia freedman and state legislator. In October 1869 Klansmen dragged him from his house and whipped him nearly to death. In 1872 he told a congressional committee what was done to him, on the record. He testified that the men broke his door open on the 29th of October 1869, took him to the woods, and whipped him for hours and left him for dead, that they asked whether he would ever vote another Radical ticket, and that he answered that if there was an election tomorrow he would vote the Radical ticket. He named the men who whipped him, men of standing in his town, a lawyer and a doctor among them. He testified further that before the whipping the men had offered him five thousand dollars to go with them, twenty five hundred in cash, if he would let another man go to the legislature in his place, and that he told them he would not do it if they would give him all the county was worth. His closing line stands in the record: no man could make a free speech in his county."),
    (6, "State the Enforcement Acts' provisions and what the federal answer of 1871 proved in South Carolina.",
     "Congress passed the three Enforcement Acts in 1870 and 1871. They made it a federal crime to conspire against citizens' constitutional rights, placed federal supervisors and federal marshals at the polls, and empowered the president to use troops and to suspend habeas corpus against insurrectionary combinations. The third act, the Ku Klux Klan Act of April 1871, made conspiracy under color of state law to deprive citizens of constitutional rights a federal offense and authorized the president to use the army against such conspiracies. Grant used the authority in South Carolina, suspending habeas corpus in nine counties in October 1871. Federal marshals and troops made hundreds of arrests, the courts took hundreds of indictments, and by 1872 the first Klan was broken in the state where its terror had run hardest. The answer proved a plain point the rest of the unit tests: federal power, used, worked. Protection had not failed for want of law or of force. It rested on a northern will to sustain it, and the next lesson follows that will giving out."),
    (7, "By what two political steps of 1872 did retreat from the settlement become respectable in the North?",
     "The first step was amnesty. The Amnesty Act of May 1872 removed the Fourteenth Amendment's officeholding disability from nearly all former Confederates, restoring the South's old leadership class to eligibility for office some seven years after the war's end. The men the settlement had barred as a condition of trust returned to the ballot and the statehouse as of right. The second step was revolt inside the governing party. The Liberal Republicans broke with Grant in 1872 over corruption and over the costs of Reconstruction, nominating Horace Greeley on a platform of amnesty, civil service reform, and an end to federal protection of the southern governments. Greeley lost, running also as the Democratic nominee, but the platform did its work: it carried the language of retreat out of the Democratic opposition and into respectable Republican print, so that leaving the southern governments to their enemies could be argued as reform rather than surrender. Thomas Nast's cartoons of these years, read in this lesson, show the same northern mind arguing with itself about what it owed and what it was tired of paying."),
    (7, "State the holding of the Slaughter-House Cases and the consequence the unit draws from it.",
     "The Slaughter-House Cases were decided in April 1873 by a vote of five to four, the Supreme Court's first reading of the Fourteenth Amendment. A Louisiana law had given one company a monopoly of New Orleans slaughtering, and white butchers sued, claiming the law abridged their privileges or immunities as citizens of the United States. The Court held that citizenship comes in two kinds, national and state, that the Fourteenth Amendment protects only the narrow rights of national citizenship, and that the great body of civil rights, the rights the butchers claimed among them, remains under state authority as it stood before the amendment. The consequence reached far beyond slaughterhouses. The amendment's first clause of protection, the clause Congress had written to carry the Civil Rights Act into the Constitution, was read down to a short list in the first case that asked what it meant. The courts had begun the narrowing of the Reconstruction amendments, and every later claim of federal protection for civil rights in the era ran through the opening this decision cut."),
    (7, "Trace the retreat from the Panic of 1873 to the Civil Rights Act of 1875, naming the White League's part.",
     "The Panic of 1873 opened with the failure of Jay Cooke's banking house in September 1873 and settled into a six year depression of closed mills, wage cuts, and unemployment. Northern attention turned from the South's unfinished settlement to hard times at home, and the elections of 1874 gave the House of Representatives to the Democrats for the first time since the war. In the South the counterrevolution changed its uniform. Louisiana's White League, formed in 1874 and pledged openly to restore white supremacy and drive Republicans from office, murdered Republican officeholders at Coushatta and fought federal troops at Liberty Place in New Orleans that year, terror organized as politics by daylight rather than by disguise. Federal troops answered at Liberty Place, and northern weariness at the answering became part of the record too. The last assertion came from the settlement's own side. Charles Sumner's Civil Rights Act was enacted in March 1875, after his death, guaranteeing all citizens equal enjoyment of inns, public conveyances, and theaters and barring racial exclusion from juries. It was the last of the Reconstruction civil rights laws, and in its own decade it was left largely unenforced, a statute standing where enforcement had stood down."),
    (8, "State the result of the election of 1876 and how the Electoral Commission settled its disputed returns.",
     "Samuel J. Tilden, the New York Democratic governor and corruption fighter, won the popular vote by some quarter of a million votes. The electoral returns of four states were disputed, Florida, Louisiana, South Carolina, and Oregon, with rival sets of returns sent to Washington, and neither candidate held the electoral majority the undisputed count could give. Congress created the Electoral Commission in January 1877, fifteen members, five senators, five representatives, and five Supreme Court justices, to judge the disputed returns. The commission awarded every disputed electoral vote to Rutherford B. Hayes, the Ohio Republican, by votes of eight to seven on party lines. Hayes took the presidency by a single electoral vote, 185 to 184. Frost's cartoon of October 1876, Of Course He Wants to Vote the Democratic Ticket, had pictured the Democratic campaign's southern arithmetic before the votes were counted: the party's road to a majority ran through the South's Black voters being counted out, which is the ground the returns fight was fought on."),
    (8, "State the terms of the Compromise of 1877 and the order that carried its central term out in April.",
     "The Compromise of 1877 was the informal bargain that settled the disputed election. Democratic leaders accepted Hayes as president. In return the Republicans pledged a cabinet seat for a southerner, support for southern internal improvements, and the withdrawal of the last federal troops protecting the Republican governments of South Carolina and Louisiana. The bargain had no statute and no signature; it was an understanding reached in the negotiations of February 1877, at the Wormley House in Washington among other rooms, and its public face was Hayes's inaugural pledge of honest local self government for the South. In April 1877 Hayes ordered the last federal troops from the statehouses at Columbia and New Orleans. The Republican governments of the two states, which had stood only while soldiers stood near them, fell, and the Redeemers governed. Federal Reconstruction, the enforcement of the settlement by the national government in the South, ended that spring, twelve years after Appomattox."),
    (8, "Audit the settlement as this unit leaves it: name three things Reconstruction settled in law and three accounts it left open.",
     "Settled in law, first, the Union: no state may leave it, a question the war decided and Reconstruction's terms assumed, with the seceded states readmitted as states of one Union on Congress's conditions. Second, slavery: abolished everywhere in the United States by the Thirteenth Amendment, with a congressional enforcement power written into the amendment itself. Third, citizenship and the vote in the Constitution's text: the Fourteenth Amendment defines citizens by birth, forbids states to abridge their privileges or immunities or to deny due process and equal protection, and the Fifteenth forbids denying the vote on account of race, color, or previous condition of servitude. Those texts stand in the Constitution now, where a later generation could take them up. Left open, first, land: emancipation came without the redistribution freedpeople asked for, and sharecropping and the crop lien filled the ground land would have held. Second, protection: the amendments' enforcement was withdrawn in 1877 and the courts had already narrowed their first reading, so rights in the text waited on a will to enforce them. Third, political power in the South: home rule under the Redeemers meant low taxes, retrenched schools, and white supremacy as a governing program, against which the settlement's survivors and their children held the texts themselves as their inheritance."),
]

FRAME = [
    "Reconstruction settled the legal frame of the American Union more deeply than any dozen years before or since, and it settled that frame in writing. The war had decided that no state may leave the Union, and the peace wrote the decision's consequences into the Constitution itself. Slavery, which the war destroyed as a system, was abolished everywhere by the Thirteenth Amendment, the first amendment in the nation's history to carry its own enforcement clause, giving Congress power over freedom's terms and not only witness to them. Citizenship, which the old law had left to the states and to a Supreme Court that had denied it to Black Americans outright, was defined by birth in the Fourteenth Amendment, which then forbade any state to abridge a citizen's privileges or immunities, to take life, liberty, or property without due process, or to deny equal protection of the laws. The Fifteenth Amendment closed the trilogy by forbidding the nation and the states to deny the vote for race, color, or previous condition of servitude. A settlement that had begun in 1865 as a president's pardon policy ended as three amendments, a body of civil rights and enforcement law, and an electorate in the South that had seated Black senators, a Black governor, and Black legislators by the hundreds. Those are not small things, and the unit has weighed them at full value.",
    "What Reconstruction left open was the ground under the frame. Land, the material base freedpeople named first in their petitions, conventions, and letters, was never redistributed: Sherman's coastal reserve was restored to its former owners, Stevens's confiscation plan was refused, and the compromise that filled the space, sharecropping financed by the crop lien, renewed a family's debt at every settlement and left freedom's economics in other men's hands. The institutions freedpeople built anyway, the schools they taxed themselves to sustain and the churches that were the first property their communities owned, stand in the record as the settlement's other half, built at speed out of nearly nothing. Protection was left open in a second way. The settlement's rights depended on federal enforcement, and enforcement depended on northern will. The Klan's terror showed what withdrawal would license, and the Enforcement Acts showed that federal power, used, could break the terror in a single year. Then the country stepped back by inches: amnesty for the old leadership, a Supreme Court narrowing the Fourteenth Amendment in its first reading, a six year depression turning northern eyes homeward, paramilitary leagues doing openly in 1874 what disguises had done in 1869, and a last civil rights act passed in 1875 and left largely unenforced in its own decade.",
    "The ending of 1877 therefore closed one thing and not the other. The Compromise that seated Hayes withdrew the last federal troops from the statehouses at Columbia and New Orleans in April 1877, and the Redeemers' home rule governed the South afterward for low taxes, cheap government, retrenched schools, and white supremacy. Federal enforcement of the settlement ended, and the political order the Reconstruction Acts had created ended with it. The settlement in law did not end. The three amendments stood in the Constitution exactly as ratified, their promises unamended and unrepealed, waiting on the will a later time would have to supply. That is the honest audit the unit's documents support. Reconstruction settled what freedom and citizenship mean in the nation's fundamental law, and whether the Union is one and indissoluble. It left open whether the country would pay the settlement's costs in land, in protection, and in sustained attention, and on those open accounts the era's survivors and their children inherited the work. A student who can hold both halves of that audit at once, the frame settled and the ground open, has the unit.",
]

